            var f = new NfaFunction[] {
                NfaIndex0, NfaIndex1, NfaIndex2, NfaIndex3, NfaIndex4, NfaIndex5, NfaIndex6, NfaIndex7, NfaIndex8, NfaIndex9, NfaIndex10, NfaIndex11, NfaIndex12, NfaIndex13, NfaIndex14, NfaIndex15, NfaIndex16, NfaIndex17, NfaIndex18, NfaIndex19, NfaIndex20, NfaIndex21, NfaIndex22, NfaIndex23, NfaIndex24, NfaIndex25, NfaIndex26, NfaIndex27, NfaIndex28, NfaIndex29, NfaIndex30, NfaIndex31, NfaIndex32, NfaIndex33, NfaIndex34, NfaIndex35, NfaIndex36, NfaIndex37, NfaIndex38, NfaIndex39, NfaIndex40, NfaIndex41, NfaIndex42, NfaIndex43, NfaIndex44, NfaIndex45, NfaIndex46, NfaIndex47, NfaIndex48
